INSERT INTO "api_mainservice" ("id", "title", "slug", "description", "image_url", "order", "color", "cta_text", "created_at", "updated_at") VALUES ('5bebf288-ba28-42f8-bd90-67c1408b9f72', 'Event Management', 'event-management', 'End-to-end event strategy including multi-channel advertisement, brand identity, and secure ticketing solutions.', '/assets/event-concert-BQ1lRCHR.jpg', 2, 'from-secondary/80 to-secondary', 'Inquire About Event Management', '2026-10-13 01:11:49.286000-07:00', '2026-10-13 01:11:49.286000-07:00');
INSERT INTO "api_mainservice" ("id", "title", "slug", "description", "image_url", "order", "color", "cta_text", "created_at", "updated_at") VALUES ('b69cc848-0d07-4a73-95fe-7eb4a5c82482', 'Event Production', 'event-production', 'From sound systems to lighting and custom stage design, we deliver world-class production for every scale.', '/assets/lighting-system-nWaROWBf.jpg', 1, 'from-primary/80 to-primary', 'Inquire About Event Production', '2026-10-13 01:11:49.278000-07:00', '2026-10-13 01:11:49.278000-07:00');
