INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('23ad9c8d-9ac8-4902-a8fb-f2a49f1e4a98', 'Sound System', 'Our professional sound systems deliver pristine audio quality for events of any size — from intimate gatherings to massive outdoor festivals. We use industry-leading equipment from brands like JBL, QSC, and d&b audiotechnik, operated by certified sound engineers who ensure every note, word, and beat is heard perfectly.', 'Volume2', '/assets/sound-system-BvTBqtrw.jpg', '2026-06-22 16:57:05.366000-07:00', 'Event Production', '[{''answer'': ''From 50-person corporate meetings to 50,000+ outdoor festivals. We scale our system to match your venue and audience.'', ''question'': ''What size events can you cover?''}, {''answer'': ''Yes — all our setups include dedicated sound engineers for seamless operation.'', ''question'': ''Do you provide sound engineers?''}, {''answer'': ''Multi-track recording and live streaming audio are available. Contact us for details.'', ''question'': ''Can I add recording services?''}]', '[''Line array & point-source systems for any venue size'', ''Wireless microphone systems (Shure, Sennheiser)'', ''Digital mixing consoles with multi-track recording'', ''Monitor systems & in-ear monitors for performers'', ''Subwoofer arrays for deep, powerful bass'', ''Certified sound engineers included'', ''Setup, sound-check & teardown handled'', ''Backup equipment on standby'']', '[''/assets/sound-system-BvTBqtrw.jpg'', ''/assets/event-concert-BQ1lRCHR.jpg'', ''/assets/hero-event-kmSdNpGf.jpg'']', '[{''label'': ''Capacity'', ''value'': ''50 – 50,000+''}, {''label'': ''Brands'', ''value'': ''JBL · QSC · d&b''}, {''label'': ''Engineers'', ''value'': ''Certified Team''}, {''label'': ''Support'', ''value'': ''24/7 On-site''}]', 'sound-system', 'Crystal-clear audio for every scale');
INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('56ccc09b-a38b-43c7-91df-171f82a5c3b0', 'Advertisement', 'Our multi-channel advertising strategies ensure maximum reach and ticket sales. We combine digital marketing, social media campaigns, influencer partnerships, and traditional media to create buzz that drives attendance and builds lasting brand awareness for your event.', 'Megaphone', '/assets/event-concert-BQ1lRCHR.jpg', '2026-06-22 16:57:05.375000-07:00', 'Event Management', '[{''answer'': ''Our campaigns typically deliver 3-8x return on ad spend, depending on event type and target audience.'', ''question'': ''What ROI can I expect?''}, {''answer'': ''Yes — all engagements include ad creative design. We can also produce video content.'', ''question'': ''Do you handle content creation?''}, {''answer'': ''Absolutely. We use advanced targeting for age, location, interests, and behavior.'', ''question'': ''Can you target specific demographics?''}]', '[''Social media ad campaigns (Meta, TikTok, X)'', ''Google Ads & display network'', ''Influencer & KOL partnerships'', ''Radio & TV ad placement'', ''Billboard & outdoor advertising'', ''Email marketing campaigns'', ''PR & press release distribution'', ''Campaign analytics & reporting'']', '[''/assets/event-concert-BQ1lRCHR.jpg'', ''/assets/event-corporate-Cw1XL7S-.jpg'', ''/assets/hero-event-kmSdNpGf.jpg'']', '[{''label'': ''Channels'', ''value'': ''10+ Platforms''}, {''label'': ''Reach'', ''value'': ''1M+ Audience''}, {''label'': ''ROI'', ''value'': ''3–8x Average''}, {''label'': ''Analytics'', ''value'': ''Real-time''}]', 'advertisement', 'Fill every seat, build the buzz');
INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('7efda4fd-b4b8-4c19-9745-1543c1428bef', 'Branding', 'We create compelling visual identities that make your event unforgettable. From logo design and color systems to printed materials and digital assets, our creative team ensures every touchpoint reflects your event''s personality and resonates with your audience.', 'Sparkles', '/assets/event-corporate-Cw1XL7S-.jpg', '2026-06-22 16:57:05.373000-07:00', 'Event Management', '[{''answer'': "Typically 3–14 days depending on the scope. We''ll discuss timelines during your consultation.", ''question'': ''How long does branding take?''}, {''answer'': ''Yes — all final designs and source files are transferred to you upon completion.'', ''question'': ''Do we own the designs?''}, {''answer'': ''Absolutely. We can extend your existing brand identity into event-specific materials.'', ''question'': ''Can you match existing branding?''}]', '[''Event logo & visual identity design'', ''Color palette & typography system'', ''Social media templates & content kits'', ''Event posters, banners & flyers'', ''Branded merchandise design'', ''Stage & venue signage'', ''Digital invitation design'', ''Brand guidelines document'']', '[''/assets/event-corporate-Cw1XL7S-.jpg'', ''/assets/hero-event-kmSdNpGf.jpg'', ''/assets/event-concert-BQ1lRCHR.jpg'']', '[{''label'': ''Turnaround'', ''value'': ''3–14 Days''}, {''label'': ''Deliverables'', ''value'': ''Print + Digital''}, {''label'': ''Revisions'', ''value'': ''Unlimited''}, {''label'': ''Ownership'', ''value'': ''Full Rights''}]', 'branding', 'Your event identity, crafted to perfection');
INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('bb1a3b17-93d4-443e-a6a5-d3bd4c38d812', 'Ticketing', 'Our end-to-end ticketing solutions handle everything from online sales and mobile money payments to QR code validation at the door. We provide real-time analytics, multiple ticket tiers, and a smooth experience for both organizers and attendees.', 'Ticket', '/assets/hero-event-kmSdNpGf.jpg', '2026-06-22 16:57:05.376000-07:00', 'Event Management', '[{''answer'': ''MTN Mobile Money, Airtel Money, Visa, Mastercard, and bank transfers.'', ''question'': ''What payment methods are supported?''}, {''answer'': ''Via email and SMS with a unique QR code. They can also access tickets in their dashboard.'', ''question'': ''How do attendees receive tickets?''}, {''answer'': ''Yes, we can provide trained check-in teams with scanning devices for your event.'', ''question'': ''Do you provide on-site check-in staff?''}]', '[''Online ticket sales platform'', ''Mobile Money integration (MTN, Airtel)'', ''Credit/debit card payments'', ''QR code ticket generation & validation'', ''Multiple ticket tiers (VIP, Standard, etc.)'', ''Real-time sales dashboard'', ''Attendee check-in system'', ''Post-event analytics & reports'']', '[''/assets/hero-event-kmSdNpGf.jpg'', ''/assets/event-concert-BQ1lRCHR.jpg'', ''/assets/event-corporate-Cw1XL7S-.jpg'']', '[{''label'': ''Payments'', ''value'': ''MoMo + Card''}, {''label'': ''Validation'', ''value'': ''QR Codes''}, {''label'': ''Dashboard'', ''value'': ''Real-time''}, {''label'': ''Support'', ''value'': ''On-site Team''}]', 'ticketing', 'Seamless ticket sales, happy attendees');
INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('c77ca0df-3359-4aaa-9ade-e28e8b4f2b58', 'Lighting System', 'Transform any space with our professional lighting systems. From elegant ambient uplighting for galas to high-energy concert rigs with moving heads and lasers, our lighting designers create immersive visual experiences that elevate your event to another level.', 'Lightbulb', '/assets/lighting-system-nWaROWBf.jpg', '2026-06-22 16:57:05.368000-07:00', 'Event Production', '[{''answer'': "Depending on complexity, setup ranges from 2 hours to a full day. We''ll coordinate the timeline with you.", ''question'': ''How early do you need to set up?''}, {''answer'': ''Absolutely. We program custom color palettes to match your brand identity perfectly.'', ''question'': ''Can you match our brand colors?''}, {''answer'': ''Yes, we have weatherproof fixtures and generators for outdoor events.'', ''question'': ''Do you provide outdoor lighting?''}]', '[''Moving head fixtures (beam, spot, wash)'', ''LED PAR cans & uplighting'', ''DMX-controlled intelligent lighting'', ''Haze & fog machines for atmosphere'', ''Truss systems & rigging'', ''Follow spots for keynote speakers'', ''Pixel-mapped LED bars & strips'', ''Dedicated lighting designer & operator'']', '[''/assets/lighting-system-nWaROWBf.jpg'', ''/assets/event-concert-BQ1lRCHR.jpg'', ''/assets/event-corporate-Cw1XL7S-.jpg'']', '[{''label'': ''Fixtures'', ''value'': ''200+ Available''}, {''label'': ''Control'', ''value'': ''Grand MA''}, {''label'': ''Setup'', ''value'': ''Same-day Ready''}, {''label'': ''Custom'', ''value'': ''Brand Colors''}]', 'lighting-system', 'Set the mood, steal the show');
INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('cf4926c0-0259-4301-8fa3-47fea0e9f049', 'Corporate Events', 'We specialize in delivering polished corporate events — from intimate board meetings to large-scale conferences and gala dinners. Our team handles every detail including venue coordination, AV production, catering, branding, and logistics so you can focus on your message.', 'Briefcase', '/assets/event-corporate-Cw1XL7S-.jpg', '2026-06-22 16:57:05.379000-07:00', 'Corporate Events', '[{''answer'': ''We recommend 4-12 weeks depending on event scale. Contact us to discuss your timeline.'', ''question'': ''How far in advance should we book?''}, {''answer'': ''Yes — we arrange airport transfers, hotel bookings, translation services, and cultural programs.'', ''question'': ''Can you handle international delegates?''}, {''answer'': ''Yes, we offer curated team-building programs including outdoor adventures, workshops, and cultural experiences.'', ''question'': ''Do you provide team-building activities?''}]', '[''Full event planning & coordination'', ''Venue sourcing & management'', ''Complete AV & production setup'', ''Corporate branding & signage'', ''Catering coordination'', ''Photography & videography'', ''Transport & logistics'', ''Post-event reporting'']', '[''/assets/event-corporate-Cw1XL7S-.jpg'', ''/assets/hero-event-kmSdNpGf.jpg'', ''/assets/stage-design-CkEBBEdx.jpg'']', '[{''label'': ''Planning'', ''value'': ''End-to-End''}, {''label'': ''Venues'', ''value'': ''50+ Partners''}, {''label'': ''Catering'', ''value'': ''Premium''}, {''label'': ''Coverage'', ''value'': ''Photo + Video''}]', 'corporate-events', 'Professional events that deliver results');
INSERT INTO "api_service" ("id", "name", "description", "icon", "image_url", "created_at", "category", "faqs", "features", "gallery_images", "highlights", "slug", "tagline") VALUES ('f131a8bf-941a-4791-a575-d978573e1440', 'Stage Design', 'Our custom stage designs are engineered for impact and safety. Whether you need a simple podium for a corporate talk or a multi-level concert stage with LED backdrops, our team designs, builds, and installs stages that become the centerpiece of your event.', 'Layers', '/assets/stage-design-CkEBBEdx.jpg', '2026-06-22 16:57:05.370000-07:00', 'Event Production', '[{''answer'': ''Yes — our fabrication team can create runways, thrust stages, circular stages, and any custom configuration.'', ''question'': ''Can you build custom shapes?''}, {''answer'': ''All our stages are structurally engineered and certified. We carry full liability insurance.'', ''question'': ''Is the stage certified safe?''}, {''answer'': ''We assist with venue and municipal permits required for stage installations.'', ''question'': ''Do you handle permits?''}]', '[''Custom stage sizes (4x3m to 20x12m+)'', ''Multi-level & runway configurations'', ''LED backdrop walls & video screens'', ''Structural engineering & safety certification'', ''Weather-rated outdoor staging'', ''VIP & speaker platforms'', ''Branded stage wraps & skirts'', ''Complete setup & teardown crew'']', '[''/assets/stage-design-CkEBBEdx.jpg'', ''/assets/hero-event-kmSdNpGf.jpg'', ''/assets/event-concert-BQ1lRCHR.jpg'']', '[{''label'': ''Sizes'', ''value'': ''4x3m – 20x12m+''}, {''label'': ''Safety'', ''value'': ''Certified''}, {''label'': ''LED'', ''value'': ''P3.9 Walls''}, {''label'': ''Crew'', ''value'': ''Full Team''}]', 'stage-design', 'The stage your event deserves');

